using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Windows.Forms;

namespace MiniPdf {
    internal static partial class SelfTest {
        static T SignatureControl<T>(Form form,string name) where T:Control {return (T)form.Controls.Find(name,true)[0];}
        static void CaptureDialog(Form form,string path){using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(path,ImageFormat.Png);}}
        static IEnumerable<Control> FindControls(Control parent){foreach(Control child in parent.Controls){yield return child;foreach(Control nested in FindControls(child))yield return nested;}}
        static bool Ink(Bitmap image){int pixels=0;for(int y=0;y<image.Height;y+=2)for(int x=0;x<image.Width;x+=2)if(image.GetPixel(x,y).A>100)pixels++;return pixels>30;}
        static void SignatureDialogFixes(string directory){UiText.English=true;using(var dialog=new SignatureWindow()){
                dialog.Show();Application.DoEvents();var name=SignatureControl<TextBox>(dialog,"signatureName");var kind=SignatureControl<ComboBox>(dialog,"signatureKind");var width=SignatureControl<NumericUpDown>(dialog,"signatureWidth");var place=SignatureControl<Button>(dialog,"placeSignature");Assert(name.Enabled&&!place.Enabled,"fresh signature dialog accepts a name and explains missing content");
                foreach(string value in new[]{"张三","王小明","Alex Rivera","Élodie Martin"}){name.Text=value;Application.DoEvents();using(var image=dialog.Build())Assert(kind.SelectedIndex==1&&place.Enabled&&Ink(image),"typing "+value+" immediately creates visible signature content");}
                name.Text="张三";width.Value=65;Assert(Math.Abs(dialog.WidthMm-65)<.01,"signature width can be set in millimeters before placement");using(var highRes=dialog.Build())Assert(highRes.Width>600,"typed name exports enough pixels for its requested physical width");CaptureDialog(dialog,Path.Combine(directory,"signature-name-fix.png"));
                using(var image=Image.FromFile(Path.Combine(directory,"signature-image.png")))dialog.LoadImage(image);Application.DoEvents();Assert(kind.SelectedIndex==2&&name.Enabled,"importing an image keeps name entry available");using(var image=dialog.Build())Assert(Ink(image)&&image.Width>image.Height*2&&image.GetPixel(0,0).A==0,"image signature removes the white background and retains full aspect ratio");
                var pad=dialog.Controls.OfType<TableLayoutPanel>().First().Controls.OfType<SignatureWindow.SignaturePad>().First();var fit=pad.FitImage(new Size(2400,800));Assert(fit.Left>=0&&fit.Top>=0&&fit.Right<=pad.Width&&fit.Bottom<=pad.Height,"entire large signature fits inside the preview instead of clipping");float previewWidth=pad.FitImage(new Size(2400,800)).Width;width.Value=25;Assert(pad.FitImage(new Size(2400,800)).Width<previewWidth*.6,"changing image width visibly resizes the signature preview");Assert(dialog.WidthMm==25&&place.Enabled,"imported image placement size is adjustable without modifying the file");CaptureDialog(dialog,Path.Combine(directory,"signature-image-fix.png"));name.Text="自己的名字";using(var image=dialog.Build())Assert(kind.SelectedIndex==1&&Ink(image),"entering a name after image import automatically switches to typed preview");place.PerformClick();Assert(dialog.Result!=null&&Ink(dialog.Result),"actual Place signature button accepts the entered name");dialog.Close();}
        }
        static void SignaturePlacementFixes(string directory){using(var form=new MainWindow(null)){form.LoadForTest(PdfDocument.Open(Path.Combine(directory,"features.pdf"),""));form.Show();Application.DoEvents();var doc=form.Document;var view=form.CanvasForTest;int before=N.FPDFPage_CountObjects(doc.Page);bool answered=false;
                using(var timer=new Timer{Interval=70}){timer.Tick+=delegate{foreach(Form open in Application.OpenForms)if(open is SignatureWindow){timer.Stop();SignatureControl<TextBox>(open,"signatureName").Text="张三";SignatureControl<NumericUpDown>(open,"signatureWidth").Value=55;SignatureControl<Button>(open,"placeSignature").PerformClick();answered=true;break;}};timer.Start();MenuItems(form.MenuButtonForTest.DropDownItems).First(i=>i.Text==UiText.Get("放置可见签名…")).PerformClick();}
                Assert(answered&&view.Mode==Tool.Image&&form.PendingSignature!=null&&!doc.Dirty,"real signature command prepares a typed name without changing the PDF yet");var r=view.PageRectangle;var point=new Point(r.Left+60,r.Top+100);N.SendMessage(view.Handle,0x200,IntPtr.Zero,Position(point));Application.DoEvents();Assert(view.SignatureBounds(point).Width>20,"signature has a visible sized placement rectangle before clicking");Mouse(view,point,point);Assert(doc.Dirty&&N.FPDFPage_CountObjects(doc.Page)==before+1&&view.Mode==Tool.Object&&view.Selected!=null&&view.Selected.Type==3,"one ordinary click places the signature and selects it for resizing");float expected=55*72/25.4f;Assert(Math.Abs(view.Selected.Bounds.right-view.Selected.Bounds.left-expected)<1,"single-click placement uses the requested physical width");doc.Save(Path.Combine(directory,"signature-click.pdf"));
                var selected=view.Selected;var bounds=view.DeviceRect(selected.Bounds);float oldWidth=selected.Bounds.right-selected.Bounds.left,oldHeight=selected.Bounds.top-selected.Bounds.bottom;var handle=new Point(bounds.Right+3,bounds.Bottom+3);Mouse(view,handle,new Point(handle.X+75,handle.Y+45));Assert(view.Selected!=null&&view.Selected.Bounds.right-view.Selected.Bounds.left>oldWidth+5,"selected signature resizes immediately from its visible corner handle");Assert(Math.Abs((view.Selected.Bounds.right-view.Selected.Bounds.left)/(view.Selected.Bounds.top-view.Selected.Bounds.bottom)-oldWidth/oldHeight)<.02,"corner resizing preserves signature proportions");doc.Undo();Assert(Math.Abs(PdfDocument.ObjectBounds(N.FPDFPage_GetObject(doc.Page,before)).right-PdfDocument.ObjectBounds(N.FPDFPage_GetObject(doc.Page,before)).left-oldWidth)<1,"signature corner resize is undoable");
                var fresh=doc.PickIndex(before);var contextPoint=view.DeviceRect(fresh.Bounds);var center=new Point(contextPoint.Left+contextPoint.Width/2,contextPoint.Top+contextPoint.Height/2);using(var timer=new Timer{Interval=60})using(var menu=form.BuildContext(center)){timer.Tick+=delegate{foreach(Form open in Application.OpenForms)if(open.Text==UiText.Get("调整对象大小")){timer.Stop();open.Controls.OfType<TextBox>().First().Text="125";((Button)open.AcceptButton).PerformClick();break;}};timer.Start();menu.Items.Cast<ToolStripItem>().First(i=>i.Text==UiText.Get("调整此对象大小…")).PerformClick();}Assert(view.Selected!=null&&view.Selected.Type==3&&Math.Abs(view.Selected.Bounds.right-view.Selected.Bounds.left-oldWidth*1.25)<1,"actual percentage resize dialog changes the signature and keeps it selected");
                using(var image=new Bitmap(300,100)){using(var g=Graphics.FromImage(image)){g.Clear(Color.Transparent);g.DrawLine(Pens.Navy,4,90,290,12);}for(int rotation=0;rotation<4;rotation++){if(rotation!=0)form.RotateView(1);Application.DoEvents();form.BeginSignature(image,35);r=view.PageRectangle;point=new Point(r.Left+35,r.Top+50);Mouse(view,point,point);var actual=view.DeviceRect(view.Selected.Bounds);Assert(Math.Abs(actual.Width/(float)actual.Height-3)<.15,"signature placement remains upright and proportional at view rotation "+(rotation*90));}form.BeginSignature(image,30);r=view.PageRectangle;point=new Point(r.Left+30,r.Top+40);Mouse(view,point,new Point(point.X+120,point.Y+80));Assert(form.PendingSignature==null&&view.Selected!=null,"dragging a placement rectangle also inserts a signature");form.BeginSignature(image,30);int objects=N.FPDFPage_CountObjects(doc.Page);Command(form,Keys.Escape);Mouse(view,point,point);Assert(N.FPDFPage_CountObjects(doc.Page)==objects&&view.Mode==Tool.Read,"Esc cancels signature placement without inserting an object");}
                using(var timer=AnswerSavePrompt(7,UiText.Get("未保存的修改"))){timer.Start();form.Close();}Application.DoEvents();}
        }
        static void SignatureReselect(string directory){using(var doc=PdfDocument.Open(Path.Combine(directory,"features.pdf"),""))using(var image=new Bitmap(80,30)){using(var g=Graphics.FromImage(image))g.DrawLine(Pens.Navy,0,25,79,2);var text=Enumerable.Range(0,N.FPDFPage_CountObjects(doc.Page)).Select(i=>doc.PickIndex(i)).First(p=>p.Type==1);var r=text.Bounds;doc.AddSignature(image,new N.Matrix{a=r.right-r.left,b=0,c=0,d=r.top-r.bottom,e=r.left,f=r.bottom});var selected=doc.PickObject(new N.Pt((r.left+r.right)/2,(r.bottom+r.top)/2));Assert(selected!=null&&selected.Type==3&&!selected.IsOcrText,"signature over body text can be reselected without choosing the text underneath");}}
        static void ExternalWatermarkFixes(string directory){using(var doc=PdfDocument.Open(Path.Combine(directory,"external-watermarks.pdf"),"")){
                doc.OpenPage(2);var first=doc.WatermarkCandidates(0);Assert(doc.Index==2&&!doc.Dirty,"inspecting external watermarks preserves current page and document state");var text=first.First(t=>t.Type==1&&t.Text=="EXTERNAL DRAFT"&&t.Bounds.top-t.Bounds.bottom>40);var image=first.First(t=>t.Type==3);var group=first.First(t=>t.Type==5);var stamp=first.First(t=>t.Annotation);Assert(!text.Tagged&&!image.Tagged&&!group.Tagged,"external text, image and form candidates require no Mini PDF tags");
                var pages=new[]{0,1,2,3};var texts=doc.MatchWatermarks(new[]{text},pages);var images=doc.MatchWatermarks(new[]{image},pages);var groups=doc.MatchWatermarks(new[]{group},pages);var stamps=doc.MatchWatermarks(new[]{stamp},pages);Assert(texts.Count==4,"external text watermark matches all four pages");Assert(images.Count==3,"image matching checks both content and position");Assert(groups.Count==2,"repeated third-party form watermark groups can be matched");Assert(stamps.Count==2,"third-party stamp annotations can be matched across pages");var targets=texts.Concat(images).Concat(groups).Concat(stamps).ToList();
                using(var dialog=new WatermarkRemovalWindow(doc)){dialog.Show();Application.DoEvents();Assert(dialog.Targets.Count==0&&!SignatureControl<Button>(dialog,"removeSelected").Enabled,"external watermark manager starts with no automatic destructive selection");SignatureControl<NumericUpDown>(dialog,"watermarkPage").Value=1;var list=(CheckedListBox)dialog.Controls[0].Controls.OfType<TableLayoutPanel>().First().Controls.OfType<CheckedListBox>().First();int mark=-1;for(int i=0;i<list.Items.Count;i++)if(((WatermarkTarget)list.Items[i]).Type==1){mark=i;break;}list.SetItemChecked(mark,true);Assert(dialog.Targets.Count==1,"checking a candidate selects that exact watermark");var matchButton=FindControls(dialog).OfType<Button>().First(b=>b.Text==UiText.Get("匹配相同水印"));matchButton.PerformClick();Assert(dialog.Targets.Count==4,"real matching button finds selected external watermark on all pages");CaptureDialog(dialog,Path.Combine(directory,"remove-external-watermarks.png"));dialog.Close();}Assert(!doc.Dirty&&doc.Index==2,"cancelling external watermark preview leaves the original untouched");
                doc.RemoveWatermarkTargets(targets);Assert(doc.Dirty&&doc.Index==2,"external watermark batch removal restores current page");foreach(int page in pages){var remaining=doc.WatermarkCandidates(page);Assert(remaining.Count(t=>t.Text=="EXTERNAL DRAFT")==1&&remaining.Any(t=>t.Text.Contains("BODY PAGE")),"page "+(page+1)+" retains body text even with the same wording as the watermark");Assert(remaining.Count(t=>t.Type==3)==(page==3?1:0)&&!remaining.Any(t=>t.Annotation||t.Type==5),"page "+(page+1)+" removes selected external image/form/stamp objects only");}doc.Save(Path.Combine(directory,"external-watermarks-removed.pdf"));doc.Undo();Assert(doc.WatermarkCandidates(0).Count==first.Count,"one undo restores all third-party watermarks and stamps");doc.Redo();Assert(doc.WatermarkCandidates(0).Count<first.Count,"external watermark removal can be redone");}
        }
        static void SignatureAndWatermarkFixes(string directory){if(!File.Exists(Path.Combine(directory,"external-watermarks.pdf"))){log.AppendLine("SKIP: signature/watermark fixes need verify_fixes.py fixtures");return;}SignatureDialogFixes(directory);SignaturePlacementFixes(directory);SignatureReselect(directory);ExternalWatermarkFixes(directory);}
        internal static int RunSignatureFixes(string directory){logPath=Path.Combine(directory,"signature-fix-test.txt");try{SignatureAndWatermarkFixes(directory);log.AppendLine("TOTAL: "+assertions+" assertions, 0 failures");File.WriteAllText(logPath,log.ToString());return 0;}catch(Exception ex){log.AppendLine(ex.ToString());File.WriteAllText(logPath,log.ToString());return 1;}}
    }
}
